n = 0; R = S.R4;
add(R, `다음 밑줄 친 표현과 바꾸어 쓸 수 있는 것은?\n\nDid you do it <u>on your own</u>?`, '1', ['alone', 'enough', 'together', 'easily', 'separately']);
add(R, `다음 <보기>에 짝지어진 단어는 서로 반의어 관계이다. 빈칸에 들어갈 접두어가 나머지와 다른 하나는?\n\n<보기>\nⓐ polite – ___polite ⓑ patient – ___patient\nⓒ possible – ___possible ⓓ formal – ___formal\nⓔ perfect – ___perfect`, '4', CIRCLE);
add(R, `다음 괄호 (A), (B), (C)에서 흐름상 알맞은 말로 바르게 연결된 것은?\n\n• It is (A)[possible / impossible] to get a table in the restaurant because it is already full.\n• Although air is everywhere, it is (B)[visible / invisible] to the eye.\n• He was wearing a suit because he had to give a (C)[formal / informal] speech.`, '2', ['(A) possible – (B) visible – (C) informal', '(A) impossible – (B) invisible – (C) formal', '(A) possible – (B) invisible – (C) formal', '(A) impossible – (B) visible – (C) formal', '(A) possible – (B) invisible – (C) informal']);
add(R, `다음 문장의 (A)~(E) 중, baking이 들어갈 위치로 알맞은 곳은?\n\nA (A) chef (B) a cake (C) is (D) my father (E).`, '2', ABCDE);
add(R, `다음 중 어법상 어색한 것은?`, '4', ['I ate a boiled egg for breakfast.', 'I heard my mom calling my name.', 'The man walking his dog asked me for help.', "Look at the little boy worn his father's big gloves.", 'The people standing in line are all waiting for the same bus.']);
add(R, `다음 문장과 의미가 같은 것은?\n\nTalent is not as important as effort.`, '2', ['Effort is not important at all.', 'Effort is more important than talent.', 'Talent is more important than effort.', 'Neither talent nor effort is important.', 'Effort is the most important in our life.']);
add(R, `다음 <보기>의 ⓐ~ⓔ 중, 어법상 알맞은 문장을 모두 골라 짝지은 것은?\n\n<보기>\nⓐ Who is the boy smiles at you?\nⓑ Sue doesn't speak so slowly as Jenny.\nⓒ Why don't we ask the man reading a book over there?\nⓓ My mom's new bag is as more expensive as her old one.\nⓔ The people taking pictures in front of the statue are from Italy.`, '5', ['ⓐ, ⓑ', 'ⓑ, ⓔ', 'ⓐ, ⓓ, ⓔ', 'ⓑ, ⓒ, ⓓ', 'ⓑ, ⓒ, ⓔ']);
add(R, `다음 빈칸 (1), (2)에 들어갈 알맞은 말을 <보기>와 같이 as ~ as ... 구문을 사용하여 각각 완성하시오.\n\n<보기>\nMegan is angry and I'm equally angry.\n→ I'm as angry as Megan.\n\n(1) Her last book is good and her new book is equally good.\n→ Her new book is ______________________.\n(2) Your clothes are clean and my clothes are equally clean.\n→ My clothes are ______________________.`, 'as good as her last book / as clean as your clothes', null, { subParts: sp(['as good as her last book', 'as clean as your clothes']) });
add(R, `다음 우리말을 주어진 <조건>에 알맞게 각각 영작하시오.${FULL}\n\n(1) Tom은 Jerry만큼 열심히 공부한다.\n(2) 내 노트북은 Mina의 것만큼 비싸다.\n\n<조건>\n• 모두 as가 포함된 동등비교 문장으로 쓸 것\n• <보기>의 단어를 사용할 것\n• (1)은 6단어, (2)는 7단어로 영작할 것\n\n<보기> hard, expensive, laptop`, "Tom studies as hard as Jerry. / My laptop is as expensive as Mina's.", null, { subParts: sp(['Tom studies as hard as Jerry.', "My laptop is as expensive as Mina's."]) });
add(R, `다음 주어진 (A)의 말에 이어질 대화가 자연스럽도록 (B), (C), (D)를 순서대로 바르게 배열한 것은?\n\n(A) Suji, how often do you take bowling lessons?\n\n(B) Twice a week. I'm just a beginner. I heard you're very good.\n(C) OK. I'll look for a lighter one, then.\n(D) Well, I love bowling. Hmm, Your bowling ball looks heavy for you. I suggest you use a lighter ball.`, '2', ['(B)-(C)-(D)', '(B)-(D)-(C)', '(C)-(D)-(B)', '(D)-(B)-(C)', '(D)-(C)-(B)']);
add(R, `다음 대화의 빈칸에 들어갈 말로 알맞은 것은?\n\nA: Mina, do you often come here to run?\nB: ______________________________\nA: Can I run with you today?\nB: Sure, but you should wear running shoes. Your shoes aren't good for running`, '2', ['I came here to run last year.', 'I come here to run every day.', 'I will come here again next week.', "Why don't we come here tomorrow?", 'I came here and ran a few days ago.']);
const SWIM128 = `Woman: Hello. Welcome to Sports World. May I help you?\nMinsu: Yes, I came to register for a swimming class. (A)\nWoman: Is this your first time taking swimming lessons?\nMinsu: Yes, it is. I don't know how to swim at all. (B)\nWoman: I see. How often do you want to take classes? (C)\nMinsu: I want to take classes twice a week. I'd like to take classes on weekdays and not on weekends.\nWoman: Then, I suggest that you take the Beginner 2 class. This class meets on Tuesdays and Thursdays. (D)\nMinsu: That sounds good. I'd like to sign up for that class. (E)\nWoman: The class has a limit of 10 people.\nMinsu: That's perfect.`;
add(R, passage(D, SWIM128, `위 대화의 (A)~(E) 중, 주어진 문장이 들어갈 알맞은 곳은?\n\nHow big is the class?`), '5', ABCDE);
add(R, passage(D, SWIM128, `위 대화의 내용과 일치하는 것은?`), '5', ['Minsu wants to take swimming lessons every other day.', 'Minsu has never taken any sports lessons before.', 'The woman encourages Minsu to take the advanced level class.', 'Minsu wants to take the classes twice a week including weekends.', 'As many as 10 people can register for the Beginner 2 class.']);
add(R, `다음 대화의 밑줄 친 (A), (B)의 우리말을 <보기>의 단어를 사용하여 각각 알맞게 영작하시오. (필요시 어법에 맞게 변형하고 (A)는 8단어, (B)는 9단어로 영작할 것)${FULL}\n\nGinny: Welcome to Sports World. May I help you?\nLuke: Yes, (A)<u>수영강좌에 등록하려고 왔어요</u>.\nGinny: Is this your first time taking swimming lessons?\nLuke: Yes, it is. I don't know how to swim at all.\nGinny: I see. How often do you want to take classes?\nLuke: I want to take classes twice a week. I'd like to take classes on weekdays and not on weekends.\nGinny: Then, (B)<u>초급 2반을 수강하기를 권합니다</u>. This class meets on Tuesdays and Thursdays.\nLuke: That sounds good. I'd like to sign up for that class. How big is the class?\nGinny: The class has a limit of 10 people.\nLuke: That's perfect.\n\n<보기>\n(A) a, come, register, class\n(B) that, suggest, the Beginner 2 class\n\n(A) ______________________\n(B) ______________________`, 'I came to register for a swimming class. / I suggest that you take the Beginner 2 class.', null, { subParts: [{ label: '(A)', answer: 'I came to register for a swimming class.' }, { label: '(B)', answer: 'I suggest that you take the Beginner 2 class.' }] });
add(R, `다음 대화의 빈칸 (A)에 들어갈 말이 되도록 <보기>에 주어진 단어를 알맞게 배열하시오.\n\nB: Suji, (A)______________________?\nG: Twice a week. I'm just a beginner. I heard you're very good.\nB: Well, I love bowling. Hmm. Your bowling ball looks heavy for you. I suggest that you use a lighter ball.\nG: OK. Thank you for your advice.\n\n<보기> bowling / do / how / lessons / you / often / take`, 'how often do you take bowling lessons', null);
const PTSH173 = `Pit Crews in Car Racing\nYou may only see the car and the driver during most car races, but there is a team behind the driver. This team is called a pit crew. A pit is a place on the side of the race track, and drivers stop there several times during a race. The main job of the pit crew is to check the car and change the tires. Changing the tires is especially important because the tires wear out (A)[easy / easily] in a high speed race.\nA pit stop can be as short as 2 seconds, and there are as many as 20 members on a crew. Therefore, the pit crew has to work in perfect harmony. The driver may get all the attention, but as people say, "Races are won in the pits."\n\nSherpas in Mountain Climbing\nThe word Sherpa comes from the Sherpa tribe, (B)[which / that] lives in the eastern part of Nepal. ⓐ<u>Sherpas have good climbing skills and know their way around the mountains well</u>. They also have little difficulty (C)[breathe / breathing] high up in the mountains. ⓑ<u>Therefore, mountain climbers started to hire Sherpas to help them climb Mount Everest</u>.\nⓒ<u>Sherpas lead mountain climbers to the top of the mountain</u>. ⓓ<u>They support climbers in many ways</u>. For example, they put up tents and carry climbers' bags. ⓔ<u>Mountain Climbers have been taking pictures of Sherpas</u>. Sherpas are often called the invisible people of Mount Everest because people often see a picture of only the climbers at the top of the mountain.`;
add(R, passage(P, PTSH173, `위 글의 괄호 (A), (B), (C)에서 어법상 알맞은 말로 바르게 연결된 것은?`), '1', ['(A) easily – (B) which – (C) breathing', '(A) easy – (B) that – (C) breathe', '(A) easily – (B) that – (C) breathe', '(A) easy – (B) which – (C) breathing', '(A) easily – (B) which – (C) breathe']);
add(R, passage(P, PTSH173, `위 글의 밑줄 친 ⓐ~ⓔ 중, 흐름상 관계없는 것은?`), '5', CIRCLE);
add(R, passage(P, PTSH173, `위 글을 읽고 답할 수 없는 질문은?`), '3', ['What is a pit?', 'What does the pit crew do in a car race?', 'For how many years can a pit crew work in a team?', 'Where does the Sherpa tribe live?', 'Why are Sherpas called the invisible people of Mount Everest?']);
add(R, `다음 글의 괄호 (A), (B), (C)에서 어법상 알맞은 말로 바르게 연결된 것은?\n\nIn sports, only the players get a trophy or medal, but they don't win on their own. There are people (A)[that / whose] help the players. These people are often hidden and don't get attention. However, they are as (B)[important / more important] as the players. Here are some examples.\n\nPacers in a Marathon\nPacers run with other runners and lead them in a marathon. Pacers are experienced runners, and their job is (C)[helping / helped] other runners manage their race better. There can be several pacers in a race.`, '2', ['(A) whose – (B) important – (C) helping', '(A) that – (B) important – (C) helping', '(A) that – (B) more important – (C) helped', '(A) that – (B) important – (C) helped', '(A) whose – (B) more important – (C) helping']);
const PTSH177 = `Pit Crews in Car Racing\nYou may only see the car and the driver during most car races, but there is a team behind the driver. This team is called a pit crew. A pit is a place on the side of the race track, and drivers stop there several times during a race. ⓐ<u>The main job of the pit crew is checking the car and change the tires</u>. ⓑ<u>Changing the tires is especially important because the tires wear out easy in a high speed race</u>.\nA pit stop can be as short as 2 seconds, and there are as many as 20 members on a crew. Therefore, the pit crew has to work in perfect harmony. The driver may get all the attention, but ⓒ<u>as people say, "Races win in the pits</u>."\n\nSherpas in Mountain Climbing\nⓓ<u>The word Sherpa comes from the Sherpa tribe, that lives in the eastern part of Nepal</u>. Sherpas have good climbing skills and know their way around the mountains well. ⓔ<u>They also have little difficulty breathe high up in the mountains</u>. Therefore, mountain climbers started to hire Sherpas to help them climb Mount Everest.\nSherpas lead mountain climbers to the top of the mountain. They support climbers in many ways. For example, they put up tents and carry climbers' bags. Sherpas are often called the invisible people of Mount Everest because people often see a picture of only the climbers at the top of the mountain.`;
